//! Generation of the gear-shaped test polygon.

use std::f64::consts::PI;

/// Builds the gear outline: `n` teeth, alternating between a point on the unit
/// circle and a point at radius 0.7 halfway to the next tooth.
///
/// The returned polygon has a single ring, matching the C++ fixture.
pub fn gear_polygon(n: i32) -> Vec<Vec<[f64; 2]>> {
    let mut polygon: Vec<Vec<[f64; 2]>> = Vec::new();
    let mut gear: Vec<[f64; 2]> = Vec::new();

    let mut i: i32 = 0;
    while i < n {
        let angle1 = 2.0 * PI * (i as f64) / (n as f64);
        let angle2 = 2.0 * PI * (i as f64 + 0.5) / (n as f64);

        gear.push([angle1.cos(), angle1.sin()]);
        gear.push([0.7 * angle2.cos(), 0.7 * angle2.sin()]);

        i += 1;
    }

    polygon.push(gear);
    polygon
}

//! A from-scratch, dependency-free port of the earcut polygon triangulation
//! algorithm.
//!
//! Input is a polygon given as a list of rings — the first ring is the outer
//! contour, any remaining rings are holes. Output is a flat list of triangle
//! vertex indices into the concatenated ring coordinates.

pub mod geom;
pub mod node;
pub mod triangulate;
pub mod zorder;

pub use self::triangulate::Earcut;

/// Triangulates `polygon` and returns the triangle index list.
pub fn earcut<R: AsRef<[[f64; 2]]>>(polygon: &[R]) -> Vec<u32> {
    let mut ec = Earcut::new();
    ec.run(polygon);
    ec.indices
}
=== node.rs ===
//! Arena-backed nodes for the circular doubly linked lists used by the
//! triangulator.
//!
//! The reference implementation threads raw pointers between heap allocated
//! nodes. Rust models the exact same topology with indices into a single
//! `Vec<Node>` arena; `NIL` plays the role of the null pointer. Node identity
//! (pointer comparison in C++) becomes index comparison here, which is
//! equivalent because nodes are never moved or reused once constructed.

/// Sentinel standing in for a null node pointer.
pub const NIL: usize = usize::MAX;

#[derive(Clone, Copy, Debug)]
pub struct Node {
    /// Index of the vertex in the flattened input coordinate sequence.
    pub i: u32,
    pub x: f64,
    pub y: f64,

    /// Previous and next vertex nodes in the polygon ring.
    pub prev: usize,
    pub next: usize,

    /// z-order curve value.
    pub z: i32,

    /// Previous and next nodes in the z-order linked list.
    pub prev_z: usize,
    pub next_z: usize,

    /// Indicates whether this is a steiner point.
    pub steiner: bool,
}

impl Node {
    pub fn new(i: u32, x: f64, y: f64) -> Node {
        Node {
            i,
            x,
            y,
            prev: NIL,
            next: NIL,
            z: 0,
            prev_z: NIL,
            next_z: NIL,
            steiner: false,
        }
    }
}

/// Growable pool of nodes. Nodes are stable for the lifetime of one
/// triangulation, so an index is a permanent handle.
pub struct Arena {
    nodes: Vec<Node>,
}

impl Arena {
    pub fn new() -> Arena {
        Arena { nodes: Vec::new() }
    }

    pub fn reserve(&mut self, additional: usize) {
        self.nodes.reserve(additional);
    }

    pub fn clear(&mut self) {
        self.nodes.clear();
    }

    /// Allocates a node and returns its handle.
    pub fn create(&mut self, i: u32, x: f64, y: f64) -> usize {
        self.nodes.push(Node::new(i, x, y));
        self.nodes.len() - 1
    }

    pub fn as_slice(&self) -> &[Node] {
        &self.nodes
    }
}

impl std::ops::Index<usize> for Arena {
    type Output = Node;

    fn index(&self, index: usize) -> &Node {
        &self.nodes[index]
    }
}

impl std::ops::IndexMut<usize> for Arena {
    fn index_mut(&mut self, index: usize) -> &mut Node {
        &mut self.nodes[index]
    }
}
